# [SAME-SCENARIO]\n# batch_translate.py – translates a list of strings while preserving order\n# Uses DeepL API (concrete provider)\nimport os\nimport requests\n\nDEEPL_AUTH_KEY = os.getenv('DEEPL_AUTH_KEY')\n\ndef _translate_single(text: str, target_lang: str) -> str:\n    url = 'https://api.deepl.com/v2/translate'\n    params = {\n        'auth_key': DEEPL_AUTH_KEY,\n        'text': text,\n        'target_lang': target_lang,\n    }\n    resp = requests.post(url, data=params)\n    resp.raise_for_status()\n    data = resp.json()\n    return data['translations'][0]['text']\n\ndef batch_translate(texts: list[str], target_lang: str = 'EN') -> list[str]:\n    """Translate each entry in `texts` preserving the original order.\n\n    Args:\n        texts: List of source strings to translate.\n        target_lang: Target language code (default 'EN').\n\n    Returns:\n        List of translated strings in the same order as `texts`.\n    """\n    return [_translate_single(t, target_lang) for t in texts]\n\n# Example usage\nif __name__ == '__main__':\n    samples = [\"Bonjour\", \"Le monde\", \"Traduction\"]\n    translated = batch_translate(samples, target_lang='EN')\n    for src, tgt in zip(samples, translated):\n        print(f\"{src} => {tgt}\")